        node_change(
            "node_removed",
            identity,
            before_node_map[identity],
            None,
        )
        for identity in sorted(before_node_ids - after_node_ids)
    ]
    node_added = [
        node_change(
            "node_added",
            identity,
            None,
            after_node_map[identity],
        )
        for identity in sorted(after_node_ids - before_node_ids)
    ]
    node_changed = [
        node_change(
            "node_changed",
            identity,
            before_node_map[identity],
            after_node_map[identity],
        )
        for identity in sorted(before_node_ids & after_node_ids)
        if before_node_map[identity] != after_node_map[identity]
    ]

    # Edges are compared by endpoint node identities, not by slice
    # positions: positions are remapped back to (cause, key) pairs.
    def edge_identity(
        edge: dict[str, object], node_map: dict[object, dict[str, object]]
    ) -> tuple[tuple[str, str], tuple[str, str], tuple[str, ...]]:
        source = node_identity(node_map[edge["source"]])
        target = node_identity(node_map[edge["target"]])
        return (source, target, tuple(edge["path"]))

    before_edges: dict[
        tuple[object, ...], dict[str, object]
    ] = {}
    for edge in before["edges"]:
        before_edges[edge_identity(edge, before_node_map)] = edge
    after_edges: dict[
        tuple[object, ...], dict[str, object]
    ] = {}
    for edge in after["edges"]:
        after_edges[edge_identity(edge, after_node_map)] = edge
    before_edge_ids = set(before_edges)
    after_edge_ids = set(after_edges)

    def edge_record(
        kind: str,
        identity: tuple[object, ...],
        edge_before: object,
        edge_after: object,
    ) -> dict[str, object]:
        # The record identity exposes the two endpoint node pairings and
        # the path, independent of either slice's positions.
        source, target, path = identity
        return {
            "kind": kind,
            "identity": {
                "source": source,
                "target": target,
                "path": tuple(path),
            },
            "before": (
                None
                if edge_before is None
                else self._copy_slice_edge(edge_before)
            ),
            "after": (
                None
                if edge_after is None
                else self._copy_slice_edge(edge_after)
            ),
        }

    edge_removed = [
        edge_record(
            "edge_removed",
            identity,
            before_edges[identity],
            None,
        )
        for identity in sorted(before_edge_ids - after_edge_ids)
    ]
    edge_added = [
        edge_record(
            "edge_added",
            identity,
            None,
            after_edges[identity],
        )
        for identity in sorted(after_edge_ids - before_edge_ids)
    ]
    # Common endpoint/path identities always carry equal content (the path
    # is part of the identity); a kept edge still changes record when
    # its endpoints' slice positions differ.
